package com.escola.gestaoescolar.sige;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:sige;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.username=sa","spring.datasource.password=","spring.datasource.driver-class-name=org.h2.Driver"})
@Transactional
class WorkspaceTest {
 @Autowired Store store;@Autowired Workspace workspace;@Autowired Academic academic;@Autowired Operations operations;
 Store.Account admin(){return store.account("admin");}
 Workspace.Transaction change(ObjectNode before,String module,ObjectNode record){String key=Modules.get(module).key();return new Workspace.Transaction(before.path("revision").asLong(),List.of(new Workspace.Change(module,"upsert",record.path(key).asText(),record)),null);}
 @Test void seedIsConsistentAndSecretsNeverReturned(){ObjectNode db=store.load();workspace.validate(db);assertEquals(30,db.path("notas").size());assertEquals(20,db.path("pagamentos").size());assertFalse(db.toString().contains("admin123"));assertTrue(admin().password().startsWith("$2"));}
 @Test void studentsPersistAndOldRevisionsFail(){ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.put("Nome","Aluno actualizado");ObjectNode result=workspace.apply(admin(),change(db,"alunos",student));assertEquals("Aluno actualizado",Store.find(store.load(),"alunos","ALU0001").path("Nome").asText());assertEquals(db.path("revision").asLong()+1,result.path("revision").asLong());assertEquals(409,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"alunos",student))).status);}
 @Test void financeCannotChangeStudents(){ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.put("Nome","Sem autorização");assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("financeiro"),change(db,"alunos",student))).status);}
 @Test void teacherCanSaveDraftWithoutChangingPublishedTerm(){
  ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();var published=grade.path("I_Trimestre").deepCopy();grade.withObject("I_Trimestre").put("MAC",19);grade.put("DraftTerm","I_Trimestre");workspace.apply(store.account("professor"),change(db,"notas",grade));
  ObjectNode saved=academic.grade(store.load(),"1","9","2026/2027");assertEquals(published,saved.path("I_Trimestre"));assertEquals(19,saved.path("Rascunhos").path("I_Trimestre").path("MAC").asInt());assertFalse(saved.path("Locks").path("I_Trimestre").asBoolean());
 }
 @Test void teacherCannotWriteOtherSubjectOrSeePayments(){ObjectNode db=store.load(),grade=academic.grade(db,"1","2","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("MAC",20);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("professor"),change(db,"notas",grade))).status);ObjectNode view=workspace.snapshot(store.account("professor"));assertEquals(0,view.path("pagamentos").size());assertEquals(0,view.path("usuarios").size());assertTrue(view.path("alunos").size()<20);}
 @Test void invalidGradesRejectEntireTransaction(){ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("MAC",21);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);assertNotEquals(21,academic.grade(store.load(),"1","9","2026/2027").path("I_Trimestre").path("MAC").asInt());}
 @Test void enrollmentMustMatchYearAndClassroom(){ObjectNode db=store.load(),enrollment=Store.find(db,"inscricoes","1").deepCopy();enrollment.put("Ano","2027/2028");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"inscricoes",enrollment))).status);}
 @Test void incompleteAssessmentCannotApproveOrRenew(){ObjectNode db=store.load();assertEquals("Em curso",academic.result(db,"1").path("situacao").asText());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(0,result.path("renovadas").asInt());}
 @Test void completedAssessmentRenewsIntoDestinationClassroom(){
  ObjectNode db=store.load();for(String subject:List.of("9","12")){ObjectNode grade=academic.grade(db,"1",subject,"2026/2027");if(grade==null){grade=db.objectNode();grade.put("IdNota",Store.next(db,"notas","IdNota"));grade.put("CodInscricao",1);grade.put("CodEscola","ESC001");grade.put("CodMateria",Integer.parseInt(subject));grade.put("Ano","2026/2027");((ArrayNode)db.path("notas")).add(grade);}for(String term:Academic.TERMS)for(String type:Academic.TYPES)grade.withObject(term).put(type,15);grade.put("ExameFinal",15);store.upsert(Modules.get("notas"),grade);}
  settle(1);assertEquals("Aprovado",academic.result(store.load(),"1").path("situacao").asText());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(1,result.path("renovadas").asInt());ObjectNode fresh=Store.find(result,"inscricoes","21"),turma=Store.find(result,"turmas",fresh.path("CodTurma").asText());assertEquals("2027/2028",turma.path("Ano").asText());assertEquals("11ª Classe",turma.path("Classe").asText());assertEquals("Pendente",fresh.path("Estado").asText());assertTrue(result.path("elegibilidadeExportacao").path("21").path("elegivel").asBoolean());
 }
 @Test void zeroWeightAndZeroNegativesRemainValid(){ObjectNode db=store.load();db.withObject("config").put("pesoExameFinal",0).put("pesoMediaAnual",1);Store.find(db,"classes","1").withObject("PorAno").withObject("2026/2027").put("MaxNegativas",0);workspace.validate(db);ObjectNode grade=academic.grade(db,"1","9","2026/2027");grade.put("ExameFinal",0);assertEquals(academic.annual(grade),academic.finalGrade(grade,db.path("config"),false));}

 void settle(int enrollment){ObjectNode db=store.load(),ins=Store.find(db,"inscricoes",String.valueOf(enrollment)),payment=db.objectNode();payment.put("IdPagamento",Store.next(db,"pagamentos","IdPagamento"));payment.put("CodAluno",ins.path("CodAluno").asText());payment.put("CodInscricao",enrollment);payment.set("CodEscola",ins.path("CodEscola"));payment.put("Referente","Propina Anual");payment.put("Talao","TESTE-"+enrollment);payment.put("Data",java.time.LocalDate.now().toString());payment.put("FormaPagamento","Numerário");payment.put("Valor",100000);store.upsert(Modules.get("pagamentos"),payment);}
 void completeFirst(){ObjectNode db=store.load();for(int subject:List.of(9,12)){ObjectNode grade=academic.grade(db,"1",String.valueOf(subject),"2026/2027");if(grade==null){grade=db.objectNode();grade.put("IdNota",Store.next(db,"notas","IdNota"));grade.put("CodInscricao",1);grade.put("CodEscola","ESC001");grade.put("CodMateria",subject);grade.put("Ano","2026/2027");((ArrayNode)db.path("notas")).add(grade);}for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).put(kind,15);grade.put("ExameFinal",15);store.upsert(Modules.get("notas"),grade);}}
 @Test void secretaryCannotPostPaymentsAndFinanceCannotEnroll(){ObjectNode db=store.load();assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("secretaria"),change(db,"pagamentos",Store.find(db,"pagamentos","1").deepCopy()))).status);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("financeiro"),change(db,"inscricoes",Store.find(db,"inscricoes","1").deepCopy()))).status);}
 @Test void decimalsAreRejectedInTermsAndExams(){ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027").deepCopy();grade.withObject("I_Trimestre").put("NPT",14.5);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);grade.withObject("I_Trimestre").put("NPT",14);grade.put("ExameFinal",13.5);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"notas",grade))).status);}
 @Test void teacherSnapshotCannotRevealOtherSubjectsOrWholeReport(){ObjectNode db=workspace.snapshot(store.account("professor"));assertTrue(db.path("resultados").isEmpty());assertTrue(db.path("propinas").isEmpty());for(var grade:db.path("notas"))assertEquals("9",grade.path("CodMateria").asText());for(var student:db.path("alunos")){assertFalse(student.has("Movel1"));assertFalse(student.has("Encarregado"));assertFalse(student.has("Morada"));}}
 @Test void newTeacherGradeStaysUnpublishedUntilValidated(){ObjectNode db=store.load(),grade=db.objectNode();grade.put("IdNota",999);grade.put("CodInscricao",11);grade.put("CodMateria",9);grade.put("Ano","2026/2027");for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).putNull(kind);grade.withObject("I_Trimestre").put("MAC",14).put("NPP",15).put("NPT",16);grade.putNull("ExameFinal");grade.putNull("ExameRecurso");grade.put("DraftTerm","I_Trimestre");ObjectNode result=workspace.apply(store.account("professor"),change(db,"notas",grade));ObjectNode saved=Store.find(result,"notas","999");assertFalse(saved.path("Locks").path("I_Trimestre").asBoolean());assertTrue(saved.path("I_Trimestre").path("MAC").isNull());assertEquals(14,saved.path("Rascunhos").path("I_Trimestre").path("MAC").asInt());}
 @Test void annualTariffsPreserveEarlierDebtAndDeriveTheTotal(){ObjectNode db=store.load(),ins=Store.find(db,"inscricoes","1"),cls=Store.find(db,"classes","3").deepCopy();double oldDebt=SchoolYear.billing(db,ins).path("divida").asDouble();ObjectNode future=cls.withObject("PorAno").withObject("2027/2028");future.put("Propina",999).put("Duracao",10).put("Inscricao",100).put("Valor",1);workspace.apply(admin(),change(db,"classes",cls));ObjectNode saved=store.load();assertEquals(10090,SchoolYear.classFor(saved,"10ª Classe","2027/2028").path("Valor").asInt());assertEquals(oldDebt,SchoolYear.billing(saved,ins).path("divida").asDouble());}
 @Test void debtPreventsRenewalEvenWhenAssessmentIsComplete(){completeFirst();ObjectNode db=store.load();assertFalse(SchoolYear.billing(db,Store.find(db,"inscricoes","1")).path("emDia").asBoolean());ObjectNode result=operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));assertEquals(0,result.path("renovadas").asInt());}
 @Test void exportChecksOriginAndConfirmationIsExplicit(){completeFirst();settle(1);ObjectNode db=store.load();operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));db=store.load();String csv=operations.exportRenewals(store.account("secretaria"),"2027/2028");assertTrue(csv.contains("ALU0001"));assertFalse(csv.contains("Encarregado"));assertFalse(csv.contains("DataNa"));assertFalse(csv.contains("Morada"));ObjectNode pending=Store.find(db,"inscricoes","21").deepCopy();pending.put("Estado","Matriculado");workspace.apply(store.account("secretaria"),change(db,"inscricoes",pending));assertEquals("secretaria",Store.find(store.load(),"inscricoes","21").path("ConfirmadoPor").asText());assertFalse(operations.exportRenewals(admin(),"2027/2028").contains("ALU0001"));assertEquals(403,assertThrows(ApiException.class,()->operations.exportRenewals(store.account("professor"),"2027/2028")).status);}
 @Test void confirmationRechecksDebtInsteadOfTrustingPreview(){completeFirst();settle(1);ObjectNode db=store.load();operations.renew(admin(),new Operations.Renewal(db.path("revision").asLong(),"2026/2027","2027/2028"));db=store.load();ObjectNode payment=Store.find(db,"pagamentos","Talao","TESTE-1");store.delete(Modules.get("pagamentos"),payment.path("IdPagamento").asText());ObjectNode current=store.load(),pending=Store.find(current,"inscricoes","21").deepCopy();pending.put("Estado","Matriculado");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(current,"inscricoes",pending))).status);assertFalse(operations.exportRenewals(admin(),"2027/2028").contains("ALU0001"));}
 @Test void tuitionFromAnotherEnrollmentNeverSettlesThisDebt(){ObjectNode db=store.load(),original=Store.find(db,"inscricoes","1");double debt=SchoolYear.billing(db,original).path("divida").asDouble();settle(2);assertEquals(debt,SchoolYear.billing(store.load(),original).path("divida").asDouble());}

 @Test void resourceRequiresBothTheClassLimitAndMinimumGrade(){completeFirst();ObjectNode db=store.load();ObjectNode rule=Store.find(db,"classes","3").withObject("PorAno").withObject("2026/2027");rule.put("MaxNegativas",0).put("NegRecurso",2).put("NotaRecurso",8);for(String subject:List.of("9","12")){ObjectNode grade=academic.grade(db,"1",subject,"2026/2027");for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).put(kind,9);grade.put("ExameFinal",9);}assertEquals("Recurso",academic.result(db,"1").path("situacao").asText());ObjectNode grade=academic.grade(db,"1","9","2026/2027");assertTrue(academic.eligible(db,grade));for(String term:Academic.TERMS)for(String kind:Academic.TYPES)grade.withObject(term).put(kind,7);grade.put("ExameFinal",7);assertFalse(academic.eligible(db,grade));assertEquals("Reprovado",academic.result(db,"1").path("situacao").asText());}
 @Test void independentExamScoresAndIntegerAverages(){completeFirst();ObjectNode db=store.load(),grade=academic.grade(db,"1","9","2026/2027");grade.put("ExameFinal",4);grade.put("ExameEspecial",20);grade.put("ExameAcesso",18);assertEquals(12.0,academic.finalGrade(grade,db.path("config"),false));assertEquals(4,grade.path("ExameFinal").asInt());assertEquals(20,grade.path("ExameEspecial").asInt());}
 @Test void secretaryCannotDeletePaymentsThroughStudentCascade(){ObjectNode db=store.load();Workspace.Transaction tx=new Workspace.Transaction(db.path("revision").asLong(),List.of(new Workspace.Change("alunos","delete","ALU0001",null)),null);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("secretaria"),tx)).status);assertNotNull(Store.find(store.load(),"alunos","ALU0001"));}
 @Test void newYearCopiesTariffsWithoutChangingEarlierYears(){ObjectNode db=store.load(),year=db.objectNode();year.put("Ano","2028/2029").put("Estado","Planeado").put("DataAbertura","2028-10-01").put("DataFecho","2029-07-15");ObjectNode result=workspace.apply(admin(),change(db,"anosLectivos",year));assertEquals(SchoolYear.classFor(db,"10ª Classe","2026/2027").path("Propina"),SchoolYear.classFor(result,"10ª Classe","2028/2029").path("Propina"));assertEquals(db.path("classes").get(0).path("PorAno").path("2025/2026"),result.path("classes").get(0).path("PorAno").path("2025/2026"));}

 String image()throws Exception{var output=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",output);return "data:image/png;base64,"+java.util.Base64.getEncoder().encodeToString(output.toByteArray());}
 ObjectNode official(String type){ObjectNode row=store.mapper().createObjectNode();return row.put("Id",90001).put("CodAluno","ALU0001").put("Tipo",type);}
 @Test void photoAndMultipleChoicesPersistTogether()throws Exception{
  ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.putArray("Deficiencias").add("Visual").add("Auditiva");student.putArray("AnexosList").add("Bilhete de Identidade").add("Fotografia Tipo Passe");student.put("Foto",image());workspace.apply(admin(),change(db,"alunos",student));
  ObjectNode saved=Store.find(store.load(),"alunos","ALU0001");assertEquals(student.path("Foto"),saved.path("Foto"));assertEquals(2,saved.path("Deficiencias").size());assertEquals("Visual, Auditiva",saved.path("Deficiencia").asText());assertFalse(Store.find(workspace.snapshot(store.account("professor")),"alunos","ALU0001").has("Foto"));
 }
 @Test void invalidImageAndInconsistentChoicesAreRejected(){ObjectNode db=store.load(),student=Store.find(db,"alunos","ALU0001").deepCopy();student.put("Foto","data:image/svg+xml;base64,PHN2Zz4=");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"alunos",student))).status);student.putNull("Foto");student.putArray("Deficiencias").add("Nenhuma").add("Visual");assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"alunos",student))).status);}
 @Test void legacyChoicesArePreserved(){ObjectNode student=store.mapper().createObjectNode();student.put("Deficiencia","Fisica").put("Anexos","Bilhete, Foto");StudentProfile.normalize(student);StudentProfile.validate(student);assertEquals("Física",student.path("Deficiencias").get(0).asText());assertEquals(2,student.path("AnexosList").size());}
 @Test void logoIsValidatedAndOnlyAdminCanChangeIt()throws Exception{ObjectNode db=store.load(),config=db.withObject("config").deepCopy();config.put("logo",image());Workspace.Transaction tx=new Workspace.Transaction(db.path("revision").asLong(),List.of(),config);assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(store.account("secretaria"),tx)).status);workspace.apply(admin(),tx);assertEquals(config.path("logo"),store.load().path("config").path("logo"));}
 @Test void officialDocumentsRequireCompletedGradesAndNoDebt(){
  ObjectNode db=store.load();assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"documentosEmitidos",official("declaracao")))).status);
  completeFirst();ObjectNode assessed=store.load();assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(assessed,"documentosEmitidos",official("certificado-freq")))).status);
  settle(1);ObjectNode paid=store.load();assertTrue(workspace.snapshot(admin()).path("elegibilidadeDocumentos").path("1").path("elegivel").asBoolean());workspace.apply(store.account("secretaria"),change(paid,"documentosEmitidos",official("certificado-conc")));assertEquals("2026/2027",Store.find(store.load(),"documentosEmitidos","90001").path("Ano").asText());
 }
 @Test void documentChecksFinalTransactionState(){completeFirst();settle(1);ObjectNode db=store.load();ObjectNode p=Store.find(db,"pagamentos","Talao","TESTE-1");var tx=new Workspace.Transaction(db.path("revision").asLong(),List.of(new Workspace.Change("documentosEmitidos","upsert","90001",official("certificado-freq")),new Workspace.Change("pagamentos","delete",p.path("IdPagamento").asText(),null)),null);assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),tx)).status);assertNotNull(Store.find(store.load(),"pagamentos",p.path("IdPagamento").asText()));assertNull(Store.find(store.load(),"documentosEmitidos","90001"));}
 @Test void diplomaRequiresLastClassAndPendingStudentsCannotGetOfficialDocuments(){completeFirst();settle(1);ObjectNode db=store.load();assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"documentosEmitidos",official("diploma")))).status);ObjectNode ins=Store.find(db,"inscricoes","1");ins.put("Estado","Pendente");assertFalse(academic.documentEligibility(db,ins).path("elegivel").asBoolean());}
 ObjectNode newPayment(String type,int amount){return store.mapper().createObjectNode().put("IdPagamento",80001).put("CodAluno","ALU0001").put("CodInscricao",1).put("Talao","TEST-CHEQUE").put("Referente",type).put("Mes","Agosto").put("Valor",amount).put("FormaPagamento","Numerário").put("Data",java.time.LocalDate.now().toString());}
 @Test void directorCannotManageConfigurationSchoolsOrYears(){
  ObjectNode db=store.load();Store.Account director=store.account("diretor");
  for(String module:List.of("escolas","anosLectivos")){
   ObjectNode row=(ObjectNode)db.path(module).get(0);
   assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(director,change(db,module,row.deepCopy()))).status);
   var deletion=new Workspace.Transaction(db.path("revision").asLong(),List.of(new Workspace.Change(module,"delete",row.path(Modules.get(module).key()).asText(),null)),null);
   assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(director,deletion)).status);
  }
  ObjectNode config=db.withObject("config").deepCopy();config.put("anoActivo","2027/2028");
  assertEquals(403,assertThrows(ApiException.class,()->workspace.apply(director,new Workspace.Transaction(db.path("revision").asLong(),List.of(),config))).status);
  assertEquals(db.path("config"),store.load().path("config"));
 }
 @Test void tuitionUsesEnrollmentYearAndPreservesHistoricPayments(){
  ObjectNode db=store.load(),historic=db.withArray("pagamentos").get(0).deepCopy(),cls=Store.find(db,"classes","3").deepCopy();
  cls.withObject("PorAno").withObject("2026/2027").put("Propina",2500).put("Duracao",8).put("Inscricao",1000);
  workspace.apply(admin(),change(db,"classes",cls));db=store.load();ObjectNode config=db.withObject("config").deepCopy();config.put("anoActivo","2027/2028");
  workspace.apply(admin(),new Workspace.Transaction(db.path("revision").asLong(),List.of(),config));
  int id=80001;for(var entry:Map.of("Propina Mensal",2500,"Propina Trimestral",7500,"Propina Anual",20000,"Taxa de Inscrição",1000).entrySet()){
   ObjectNode payment=newPayment(entry.getKey(),entry.getValue()).put("IdPagamento",id).put("Talao","AUTO-"+id++);
   workspace.apply(store.account("financeiro"),change(store.load(),"pagamentos",payment));
  }
  assertEquals(historic,Store.find(store.load(),"pagamentos",historic.path("IdPagamento").asText()));
 }
 @Test void wrongTuitionAmountIsRejectedAtomically(){
  ObjectNode db=store.load(),payment=newPayment("Propina Trimestral",1);
  assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"pagamentos",payment))).status);
  assertNull(Store.find(store.load(),"pagamentos","80001"));assertEquals(db.path("revision"),store.load().path("revision"));
 }
 @Test void chequeNumberIsRequiredStoredAsTextAndRemovedForCash(){
  ObjectNode db=store.load(),payment=newPayment("Outro",1000).put("FormaPagamento","Cheque");
  assertEquals(422,assertThrows(ApiException.class,()->workspace.apply(admin(),change(db,"pagamentos",payment))).status);
  payment.put("NumeroCheque","  00001234  ");workspace.apply(store.account("financeiro"),change(db,"pagamentos",payment));
  ObjectNode saved=Store.find(store.load(),"pagamentos","80001").deepCopy();assertEquals("00001234",saved.path("NumeroCheque").asText());
  saved.put("FormaPagamento","Numerário");workspace.apply(store.account("financeiro"),change(store.load(),"pagamentos",saved));assertFalse(Store.find(store.load(),"pagamentos","80001").has("NumeroCheque"));
 }
}
